import json

def transform(input_grid):
    h = len(input_grid)
    if h == 0:
        return input_grid

    # Find first separator row (all values same)
    separator_row = None
    for i, row in enumerate(input_grid):
        if len(set(row)) == 1:
            separator_row = i
            break

    if separator_row is None:
        return input_grid

    top_block = input_grid[:separator_row]
    separator = input_grid[separator_row]

    output = []
    remaining_rows = h

    while remaining_rows > 0:
        if top_block and remaining_rows > 0:
            for r in top_block:
                if remaining_rows <= 0:
                    break
                output.append(r)
                remaining_rows -= 1

        if remaining_rows <= 0:
            break

        if separator and remaining_rows > 0:
            output.append(separator)
            remaining_rows -= 1

    return output

