def transform_cross(input_grid):
    h = len(input_grid)
    w = len(input_grid[0]) if h > 0 else 0

    sep_row = None
    for i in range(h):
        if len(set(input_grid[i])) == 1:
            sep_row = i
            break

    if sep_row is None:
        return input_grid

    sep_col = None
    for j in range(w):
        col_vals = [input_grid[i][j] for i in range(h)]
        if len(set(col_vals)) == 1:
            sep_col = j
            break

    if sep_col is None:
        return input_grid

    left_width = sep_col
    right_width = w - sep_col - 1

    output = [row[:] for row in input_grid]

    for i in range(h):
        if i == sep_row:
            continue

        if i > sep_row:
            top_row = i - sep_row - 1
        else:
            top_row = i

        if top_row < sep_row:
            left_pattern = input_grid[top_row][:left_width]

            output[i][:left_width] = left_pattern

            if right_width > 0 and len(left_pattern) <= right_width:
                output[i][sep_col+1:sep_col+1+len(left_pattern)] = left_pattern

    return output

